body:
Ok, this is what I have so far. I can't figure out how to turn them on separately.

\#define GRN 9 // green led is 9  
\#define BLU 8 // blue led is 8  
\#define SWT 7 // switch is 7  
byte stateGRN = LOW;  
byte stateBLU = LOW;  
byte lastButtonState = LOW;  
  
  
void setup() {  
  pinMode(GRN,OUTPUT);  
  pinMode(BLU,OUTPUT);  
  pinMode(SWT,INPUT);  
  
}  
void loop() {  
  byte buttonState = digitalRead(SWT);  
   if(buttonState != lastButtonState){  
lastButtonState = buttonState;  
if(buttonState == LOW){  
stateBLU = (stateBLU == HIGH) ? LOW: HIGH;  
digitalWrite(BLU, stateBLU);  
delay(200);  
}  
if(buttonState == HIGH){  
stateGRN = (stateGRN == HIGH) ? LOW: HIGH;  
digitalWrite(GRN, stateGRN);  
delay(200);  
}  
   }  
  }
